// Generated by scripts/generate-workflow-blueprints.ts (extra questions); edit the specs there and re-run rather than editing by hand.
import { o, s, type QuestionSet } from "@/lib/interview-questions";

const bank: QuestionSet = {
  subjective: [
    s(5, "Walk me through the end-to-end architecture of this scheduled ingestion flow.", "An external scheduler such as cron, a CI job or an orchestrator fires on a fixed interval. It calls POST /api/v1/run/<flow-id> with an API key and tweaks for the source path, target collection and a reindex flag. Inside Langflow, a custom change-detector hashes source files and compares them with the ingest manifest. It passes new or changed files forward and emits deletes for removed ones. File loaders read the text, and a custom metadata component attaches doc_id, path, hash, model name and access tags. The text splitter creates chunks with deterministic ids. The embeddings component embeds them in batches, and the vector store component deletes old chunks per doc_id and then upserts the new ones. Finally the manifest is updated, a run report goes to the team, and traces are kept in LangSmith or Langfuse."),
    s(5, "Why compare content hashes against a manifest instead of relying on file modified times?", "Modified time tells you a file was touched, not that its content changed. A copy, a checkout or a sync tool can reset timestamps and trigger expensive re-embedding of identical text. Clocks can also be wrong or get preserved during a copy, so a real change could be missed. A content hash changes only when the bytes change, which makes the decision deterministic and repeatable. The manifest stores the last successfully ingested hash per document, so comparing the two gives three clear sets: new, changed and unchanged. Removed files show up as entries in the manifest that no longer exist in the source. I still record modified time as metadata, because it is useful for display and for freshness filters."),
    s(5, "How do you guarantee that access tags are never dropped on the way to the vector store?", "I treat access tags as a required field, not a nice-to-have. The custom metadata component looks up tags from the source system or a mapping file. If a document has no resolvable tag, it fails closed: the document is marked failed or skipped and is never upserted untagged. The splitter must copy document metadata onto every chunk, and just before the upsert I add a validation step that checks every chunk for doc_id, content hash, embedding model and tenant or access tags. I also add a test fixture that asserts tags survive splitting. Retrieval flows should always apply a tag filter, so a missing tag hides content instead of exposing it. The run report counts these rejections so someone fixes the mapping."),
    s(5, "A document shrinks from ten chunks to seven. Why is upserting by id alone not enough?", "Upsert by deterministic id overwrites chunks 0 to 6. Chunks 7, 8 and 9 from the old version are never touched, so they stay in the index as stale content and can still be retrieved. That is why the vector store step first deletes all chunks matching the changed doc_id and then upserts the new set. An alternative with a smaller gap is to upsert the new chunks first and then delete any chunk for that doc_id whose id is not in the new set, or whose content hash differs from the new hash. Both approaches depend on doc_id being stored as filterable metadata on every chunk, which is another reason that metadata must never be lost."),
    s(4, "What happens if the run crashes between deleting old chunks and upserting new ones?", "With delete-then-upsert, that document has no chunks until the next successful run, so retrieval silently misses it. The key protection is that the manifest is updated only after the upsert succeeds. On the next run, the hash still differs from the manifest, so the document is reprocessed and the state heals itself. To shrink the gap, I can reorder the steps: upsert the new chunks, then delete old chunks for that doc_id that are not in the new id set. Readers briefly see the new content plus a few leftovers instead of nothing. For strict needs, I build a fresh collection and switch retrieval to it only after validation."),
    s(4, "What does the ingest manifest store, and where would you keep it?", "Per document, the manifest stores doc_id, source path, the last ingested content hash, the embedding model name, the chunk count or chunk ids, the status (ingested, skipped or failed), an error reason and a last run timestamp. It must be durable and outside the flow's memory, because each run is stateless. A small relational table or a key-value store works well. A JSON file in object storage is fine for small corpora, but it needs care with concurrent writers. The manifest is the source of truth for what the pipeline believes is indexed, so updates should happen per document after a successful upsert, not once at the start of the run."),
    s(4, "How do you make a run idempotent if the scheduler retries or fires twice?", "Several design choices together make reruns safe. Deterministic chunk ids built from doc_id and chunk index mean an upsert replaces rather than duplicates. The delete for a doc_id is safe to repeat. The change detector compares against the manifest, so a document finished in an earlier attempt shows as unchanged and is skipped. The manifest is written only after success, so partial work is redone rather than lost. The remaining risk is two runs at the same time interleaving deletes and upserts on one document. I prevent that with a lock, such as a row in the manifest database or the orchestrator's single-concurrency setting, and a second trigger either exits or waits."),
    s(4, "How would you choose chunk size and overlap for the text splitter?", "I start from how the content will be retrieved and answered. Chunks should be large enough to hold a complete idea, such as a section or a procedure step, and small enough that one retrieved chunk is mostly relevant. They must also fit within the embedding model's input limit. Overlap keeps sentences that cross a boundary findable from either side, but it increases storage and embedding calls. I would not guess: I build a small evaluation set of real questions with known answer passages, try two or three size and overlap settings, and measure retrieval hit rate. The chosen values become part of the configuration, and changing them means a full reindex."),
    s(4, "How do you handle embedding failures without losing documents?", "The embeddings component sends chunks in batches, and transient errors such as rate limits or timeouts get retries with backoff. If a batch still fails, its documents go onto a failed-docs list with the error, and their manifest entries are not updated to the new hash. That means the next run sees them as changed and tries again. I avoid upserting part of a document: if any of its chunks failed, the whole document is treated as failed, so the index never holds a half-updated version. The run report shows the failed count, and an alert fires if the same document fails repeatedly, which usually points to bad input rather than a flaky provider."),
    s(4, "How would you secure the run endpoint and the API key the scheduler uses?", "The Langflow API key lives in the scheduler's secret store, such as CI secrets or the orchestrator's vault, and never in the repo or the flow export. I use a dedicated key for this job so it can be rotated or revoked on its own. The Langflow server should not be open to the public internet. I put it behind a private network or gateway with TLS. Tweaks are powerful because they can change the source path or target collection, so I restrict the allowed values in the custom components, for example with an allow-list of source roots and collections. Credentials for the vector store and embedding provider are kept as Langflow secrets or environment variables, not in plain component fields."),
    s(4, "Access permissions on a document change but its content does not. How does the pipeline notice?", "With a pure content hash, it won't notice, and that is a security bug, because retrieval would keep filtering on the old tags. I fix this by computing a second fingerprint over the metadata that matters, especially access and tenant tags, and storing it in the manifest. The change detector treats a change in either the content hash or the metadata fingerprint as a change. For a metadata-only change I could update metadata in place if the vector store supports it. The simpler and safer path is to rerun the delete and upsert for that doc_id. If permissions change often, an event-driven trigger from the permission system is better than waiting for the next scheduled run."),
    s(4, "How do you enforce tenant isolation in a shared vector store?", "Every chunk carries a tenant id and access tags in its metadata, set by the metadata component and checked before the upsert. Retrieval flows must always apply a filter on tenant and permitted tags. That filter comes from the authenticated user's context, never from free text in the prompt. For stronger isolation, or for tenants with contractual requirements, I use separate collections per tenant and pass the target collection name through tweaks. Separate collections cost more to operate but make cross-tenant leaks much harder and make deleting one tenant's data simple. Either way, I add a test that queries as tenant A and asserts that no tenant B chunks come back."),
    s(4, "How would you test this flow before it runs against production data?", "First, I build in the canvas and run it in the Playground against a small fixture folder. The folder covers a new file, an edited file, a deleted file, an empty file, an unsupported format and a document without access tags. I check the vector store directly: the expected chunk counts, no orphan ids and metadata present on every chunk. Then I run it twice to prove idempotency, because the second run should report zero changes. I call the API with tweaks pointing at a staging collection so production is never touched. The custom components are Python classes, so I unit test the change-detector and metadata logic outside Langflow. Traces in LangSmith or Langfuse help me inspect each step."),
    s(3, "Why record unsupported or empty files as skipped instead of failing the whole run?", "One bad file should not block thousands of good updates. If the run failed on the first odd PDF, the whole knowledge base would go stale until someone intervened. Recording the file as skipped with a reason keeps the run going and gives a clear list to act on. The skip is written to the manifest, so it is visible and is not retried every night unless the file's hash changes. The risk is silent gaps, so the skipped count appears in the run report, and a sudden jump in skips, for example after a source system starts exporting a new format, should raise an alert."),
    s(3, "How would you choose the doc_id, and what happens when a file is renamed?", "The doc_id should be stable for the life of a document. If the source system offers a stable id, such as a CMS page id or a drive file id, I use it. If I only have paths, the doc_id is derived from a normalised path, which means a rename or move looks like a delete plus a new document. That is still correct: the old chunks are deleted and new ones are created. The cost is re-embedding unchanged text. If renames are common, I can detect them by matching the content hash of a vanished file with that of a new file and reuse the embeddings. I would add that only if the cost justifies it."),
    s(3, "How would you estimate how long and how much a nightly run takes?", "I estimate from our own measurements, not assumptions. The work scales with changed content, not total corpus size. Embedding calls are roughly the number of changed chunks divided by the batch size, and the chunk count is the changed text length divided by the chunk size minus overlap. I measure average latency per batch and the provider's rate limit, and those give the wall-clock time. Cost is the number of tokens embedded times the provider's current published rate. Vector store writes scale with upserted plus deleted chunks. For a full reindex I apply the same formula to the whole corpus, which is why reindexes are planned rather than accidental."),
    s(3, "How does this design scale to a very large corpus?", "The incremental design already helps, because a normal run touches only changed files. The bottlenecks become listing and hashing the source, embedding throughput and vector store write rate. For listing, I use the source system's change feed or modified-since queries to avoid hashing everything, and then hash only the candidates. For throughput, the scheduler can shard the work by calling the flow several times with tweaks for different source paths. Each shard has its own lock, and all of them write to the same manifest. Batches are sized to provider limits. A full reindex goes into a new collection in the background, so the live index stays usable."),
    s(3, "How do you observe a run and know it worked?", "There are three layers. Traces in LangSmith or Langfuse show each component's inputs, outputs, timings and errors, so I can see exactly where a document failed. The run report summarises added, updated, deleted, skipped and failed counts and is sent to the team's channel. Alerts fire on conditions such as the run not happening at all, failed counts above a threshold, the same document failing repeatedly, or a deleted count that is suspiciously large. That last one often means the source mount was empty, and in that case the pipeline should stop before deleting rather than wipe the index."),
    s(3, "How would you protect against an accidental mass delete when the source is unreachable?", "If the source path is empty because a mount failed or credentials expired, the change detector would see every manifest entry as deleted. I add a safety check: if the delete set is above a threshold, either a percentage of the corpus or an absolute count, the run stops before any deletion and alerts. A source listing error is treated as a failure, not as an empty folder. Large deletes then require an explicit tweak, such as an allow-mass-delete flag, on a manual run. I also rely on the manifest and versioned collections so a bad run can be reversed."),
    s(3, "How would you reconcile the vector store with the manifest over time?", "Even with careful logic, drift happens through manual edits, partial failures or bugs. I run a periodic reconciliation job, often weekly, that lists distinct doc_ids and their content hashes from the vector store metadata and compares them with the manifest. Doc_ids found in the store but not in the manifest are orphans to delete. Manifest entries with no chunks are re-queued. Chunks whose hash or embedding model differs from the manifest are stale and get reingested. This depends on doc_id, content hash and model name being stored on every chunk. The job reports its findings before fixing anything, so a bug in it cannot wipe the index."),
    s(3, "How do retrieval flows actually use the metadata this pipeline writes?", "Retrieval flows query the same vector store collection and pass metadata filters alongside the similarity search. The tenant and access tags restrict results to what the user may see. Document type or source path narrows the search to, say, policies only. Version or modified time can prefer the latest content. Title and source path are returned with each chunk so the answer can cite its source. The embedding model name lets a retrieval flow confirm it is embedding the query with the same model. If ingestion drops a field, the retrieval filter either leaks data or returns nothing, which is why metadata is validated before the upsert."),
    s(3, "When would you trigger a full reindex instead of an incremental run?", "I trigger a full reindex when the meaning of existing vectors or chunks changes. That covers a new embedding model, new chunk size or overlap, a change to the metadata schema that retrieval depends on, a splitter or loader fix that changes extracted text, and recovery after confirmed drift or corruption. The scheduler passes the full-reindex flag as a tweak, and the change detector then treats every file as changed. I prefer writing into a new target collection, also set by tweak, validating it and then pointing retrieval at it. That avoids a period where the live index mixes old and new chunks."),
    s(3, "What are the trade-offs between scheduled batch ingestion and event-driven ingestion via webhooks?", "A schedule is simple, predictable and easy to rate-limit. The full change detection also catches anything missed, such as events that were never sent. The cost is freshness: an edit waits until the next run, which matters for permission changes. Webhooks, which Langflow supports, give near-real-time updates per document, but you must handle bursts, duplicate or out-of-order events, and missed events. A common design combines them. Webhooks handle urgent single-document updates, especially access changes, and a scheduled run reconciles everything. Both paths share the same components and deterministic ids, so they converge on the same state."),
    s(3, "How would you handle PII or sensitive content found in source files?", "First, I decide policy with the data owner: exclude these sources, redact the content, or index it with tight access tags. Exclusion is handled in the change detector through allow-lists of paths or document types. Redaction belongs in a custom component placed before splitting, so raw PII is never embedded or stored as chunk text. Remember that the embedding provider receives the text, so data residency and the provider's retention terms matter. Traces in LangSmith or Langfuse can also capture document text, so I check what is logged and mask it or reduce the detail. Deletion requests must flow through the same delete-by-doc_id path."),
    s(3, "When do you write a custom component instead of using built-in ones?", "I use built-in loaders, the text splitter, embeddings and vector store components wherever they fit, because they are maintained and easy to read on the canvas. I write custom components, which are Python classes with defined inputs and outputs, for logic specific to our pipeline. Here that means the change detector with manifest comparison and the metadata component with tag lookup and validation. Custom code should be small, unit tested and free of hard-coded secrets. I keep it in version control, because the flow and its components are part of the pipeline's contract, not just canvas settings."),
    s(3, "How do you handle large files and embedding provider rate limits?", "Large files are streamed or split by the loader where possible, and they produce many chunks, so I cap the chunks per batch to stay within the provider's request and token limits. Batches run with bounded concurrency, and on rate-limit responses they back off with jitter instead of retrying immediately. A single huge file should not starve the rest, so I can process it in its own batches and give it a per-document time budget. If it exceeds that budget, it goes to the failed-docs list. Very large files often signal exports or logs that do not belong in the knowledge base, so size limits with a skip reason are reasonable."),
    s(2, "How would you roll back a bad ingestion run?", "Rollback is easiest when ingestion never overwrites the only good copy. For large or risky changes, I write into a new target collection set through tweaks, validate it with test queries and counts, and then switch retrieval to it while keeping the old collection for a while. For routine incremental runs, the source files themselves are the backup. I revert the bad source change or the bad component version, then rerun for the affected doc_ids, or do a full reindex into a fresh collection. Keeping flow exports and custom components in version control lets me redeploy the previous pipeline exactly."),
    s(2, "Would you expose this ingestion flow as an MCP tool for agents?", "Langflow can act as an MCP server and expose flows as tools, so it is technically easy. I would be careful, though. Ingestion writes to and deletes from the knowledge base, so an agent calling it with a wrong source path or the reindex flag could do real damage. If I expose it, I expose a narrow version: reingest a single named document, restricted to allowed sources and collections, with no mass delete, plus authentication and logging. Read-only tools such as checking a document's ingest status are safer to share. The scheduled job stays the main path, called directly through the API."),
    s(2, "Why should each chunk store the content hash and embedding model name, not just the manifest?", "The manifest is what the pipeline believes. The chunk metadata is what is actually in the index. Storing the hash on each chunk lets a reconciliation job detect stale chunks whose hash no longer matches the current document. It also lets the upsert-then-delete approach remove leftovers by hash. Storing the embedding model name lets you find vectors from an old model during a migration, and lets retrieval check that the query is embedded with a matching model. Without these fields, verifying the index means re-reading and re-embedding everything, which defeats the point of incremental ingestion."),
    s(2, "Why does this flow not need message history or chat memory?", "Message history in Langflow gives per-session chat memory, which suits conversational flows where a session id ties turns together. This flow is a batch job triggered by a scheduler, not a conversation. Each run is driven by its tweaks and by durable state in the manifest and the vector store. Using chat memory as state would be wrong, because it is not designed as a reliable ledger of what was ingested. Keeping the flow stateless between runs, with all persistent state in the manifest, makes it restartable, easy to shard and easy to reason about."),
  ],
  objective: [
    o(5, "Which call does the scheduler make to trigger the Langflow ingestion flow?", ["POST /api/v1/run/<flow-id> with an API key and optional tweaks","GET /api/v1/flows/<flow-id>/start with no authentication","A chat message sent to the Playground","A direct write into the vector store that Langflow then detects"], 0, "Flows run through the API at POST /api/v1/run/<flow-id>, authenticated with an API key, and tweaks can override component settings."),
    o(5, "What are tweaks used for in this pipeline?", ["Permanently editing the saved flow graph","Overriding component settings for a single run, such as source path or target collection","Storing chat memory per session","Encrypting metadata before it is stored"], 1, "Tweaks override component settings for that run only, so one flow can serve different sources, collections or a reindex flag."),
    o(5, "A document shrinks from 10 chunks to 7 and is only upserted by deterministic id. What is the result?", ["Seven chunks are stored and no stale data remains","The upsert fails because of an id conflict","Chunks 7 to 9 from the old version remain as stale chunks","All ten chunks are duplicated"], 2, "Upsert overwrites ids 0 to 6 but never touches 7 to 9, so old chunks must be deleted by doc_id."),
    o(5, "How does the change-detector component decide which files to pass forward?", ["It passes every file on every run","It uses only the file size","It asks the embeddings model whether the text is new","It computes a content hash per file and compares it with the ingest manifest"], 3, "Only files whose hash is new or differs from the manifest are passed on, and files missing from the source produce delete instructions."),
    o(5, "A chunk reaches the vector store step without any access tag. What is the safest behaviour?", ["Reject it and record the document as failed or skipped (fail closed)","Upsert it with a default public tag","Upsert it and fix the tags in a later run","Drop the tag field from all chunks for consistency"], 0, "Untagged chunks could leak through retrieval filters, so validation must block them rather than guess."),
    o(4, "How is each chunk id built in this design?", ["A random UUID generated at split time","From doc_id and chunk index, deterministically","From the current timestamp","By the vector store auto-increment counter"], 1, "Deterministic ids from doc_id and chunk index make reruns overwrite rather than duplicate chunks."),
    o(4, "What happens to an empty or unsupported file during a run?", ["The whole run fails","It is embedded as an empty vector","It is recorded as skipped and the run continues","It is silently ignored with no record"], 2, "Skipping with a recorded reason keeps one bad file from blocking the rest while staying visible in the report."),
    o(4, "When should the manifest entry for a document be updated with its new hash?", ["At the start of the run, before loading","Right after the file is loaded","Right after splitting","After its chunks have been successfully upserted"], 3, "Updating only after success means a failed document still looks changed and is retried next run."),
    o(4, "An embedding batch still fails after retries. What does the pipeline do?", ["Writes the affected documents to a failed-docs list for the next run","Deletes the source files","Upserts the chunks without vectors","Marks the documents as ingested to avoid loops"], 0, "The failed-docs list, together with the unchanged manifest hash, ensures the next run picks those documents up."),
    o(4, "Why is a scheduled external trigger used rather than a chat input?", ["Chat inputs cannot call vector stores","The refresh is driven from outside on a fixed interval, not by a user message","Langflow flows cannot run without a scheduler","Schedulers make embeddings cheaper"], 1, "Ingestion is a batch job on a timetable, so an external scheduler calling the API fits better than a conversational trigger."),
    o(4, "Only a document's access tags changed; its text is identical. With a content-only hash, what happens?", ["Tags are updated automatically on the next run","The document is deleted","The change is missed and chunks keep the old tags","The run fails with a hash conflict"], 2, "The content hash is unchanged, so the detector needs a metadata fingerprint too, or permission changes are silently ignored."),
    o(4, "Why does every chunk inherit the full document metadata?", ["To make embeddings more accurate","To reduce storage","Because the splitter requires it to run","Because retrieval filters are applied per chunk, so each chunk needs tags and doc_id"], 3, "Vector search returns chunks, so filtering by tenant, access or doc_id only works if every chunk carries those fields."),
    o(4, "Where should the scheduler's Langflow API key be stored?", ["In the scheduler's secret store, with a dedicated key for this job","Hard-coded in the cron script in the repo","Inside a tweak value visible in logs","In the flow's exported JSON"], 0, "A dedicated key in a secret store can be rotated or revoked and is kept out of code and exports."),
    o(4, "Which tracing integrations do the reference notes name for Langflow?", ["Only Prometheus","LangSmith and Langfuse","Langflow has no tracing integrations","Only the browser console"], 1, "LangSmith and Langfuse are the named tracing integrations for inspecting runs."),
    o(3, "What is a Langflow custom component?", ["A YAML file describing a prompt","A hosted model endpoint","A Python class with defined inputs and outputs","A canvas colour theme"], 2, "Custom components are Python classes with inputs and outputs, used here for change detection and metadata."),
    o(3, "What would happen if chunk ids were random UUIDs generated on every run?", ["Reruns would overwrite chunks correctly","Retrieval would become faster","Metadata filters would stop working","Each rerun would add duplicate chunks alongside the old ones"], 3, "Random ids never match previous ones, so upserts insert new rows instead of replacing, creating duplicates."),
    o(3, "Why store the embedding model name on each chunk?", ["To detect vectors from an old model during migration and avoid mixing models","To choose the chunk size automatically","Because the vector store requires it as the primary key","To display in the chat UI"], 0, "Vectors from different models are not comparable, so the model name lets you find and replace stale ones."),
    o(3, "What is the main purpose of chunk overlap?", ["Reducing the number of chunks","Keeping text that crosses a chunk boundary retrievable from either side","Encrypting chunk text","Speeding up hashing"], 1, "Overlap preserves context at boundaries, at the cost of extra storage and embedding calls."),
    o(3, "Two scheduled runs overlap on the same source. What is the best safeguard?", ["Let them both run; upserts are safe","Double the batch size","Use a lock so only one run per source executes at a time","Disable deletes"], 2, "Concurrent runs can interleave deletes and upserts for the same doc_id, so a per-source lock prevents races."),
    o(3, "A source file is touched by a sync tool, but its bytes are unchanged. With content hashing, what happens?", ["It is re-embedded","It is deleted","It is skipped as unsupported","It is treated as unchanged and not re-embedded"], 3, "The hash matches the manifest, so no work is done, unlike a modified-time check."),
    o(3, "The source mount fails and the change detector sees zero files. What should the pipeline do?", ["Stop before deleting and alert, because a mass delete exceeds the safety threshold","Delete every document in the manifest","Run a full reindex","Mark all documents as skipped and continue"], 0, "An empty listing usually means a source failure, so a delete threshold prevents wiping the index."),
    o(3, "How would the scheduler request a full reindex for one run?", ["Edit the custom component code each time","Pass a full-reindex flag as a tweak in the run request","Delete the Langflow database","Send the flag through chat memory"], 1, "Tweaks override component settings per run, including a reindex flag the change detector honours."),
    o(3, "Roughly how many embedding calls does an incremental run make?", ["Total corpus documents times batch size","One per file regardless of size","Number of changed chunks divided by batch size","Number of deleted files"], 2, "Only changed content is embedded, and batching groups chunks per call."),
    o(3, "In a shared collection, how is tenant isolation enforced at query time?", ["By the embedding model","By chunk overlap","By the order of upserts","By a metadata filter on tenant and access tags derived from the user's identity"], 3, "Tenant and access tags stored with each vector let retrieval filter results to what the user may see."),
    o(3, "With a path-based doc_id, how does a file rename appear to the pipeline?", ["As a delete of the old doc_id plus a new document","As an unchanged document","As a skipped file","As a failed embedding"], 0, "A new path gives a new doc_id, so the old chunks are deleted and the content is ingested as new."),
    o(2, "Which counts does the run report include?", ["Only total tokens","Added, updated, deleted, skipped and failed","Only failures","Number of chat sessions"], 1, "The report summarises each outcome so the team can spot gaps such as skips or failures."),
    o(2, "Which Langflow feature is least relevant to this scheduled ingestion flow?", ["Custom components","The API run endpoint with tweaks","Message history for per-session chat memory","Tracing integrations"], 2, "Ingestion is a stateless batch job with state in the manifest, so session chat memory plays no role."),
    o(2, "What is the safest way to apply a risky change such as a new chunk size?", ["Edit chunks in place in the live collection","Delete the live collection first, then ingest","Run incremental ingestion only for new files","Ingest into a new collection via tweak, validate it, then switch retrieval"], 3, "Building a separate collection avoids mixed or missing content and keeps the old one for rollback."),
    o(2, "What does it mean that Langflow can act as an MCP server?", ["It can expose flows as tools to MCP clients","It replaces the vector store","It schedules flows automatically","It encrypts API keys"], 0, "As an MCP server, Langflow makes flows callable as tools by MCP clients."),
    o(2, "Besides the scheduled API call, which other trigger does Langflow support for event-driven updates?", ["Email polling built into the vector store","Webhooks","Only manual Playground runs","Database triggers inside the embeddings component"], 1, "Langflow flows can be run through the API or webhooks, so webhooks suit near-real-time single-document updates."),
  ],
};
export default bank;
